export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mirrorConfig(input){const c=structuredClone(input),m=c.bounds[0]+c.bounds[2],point=p=>[m-p[0],p[1]],vector=p=>[-p[0],p[1]];for(const w of c.walls){w.a=point(w.a);w.b=point(w.b);for(const o of w.openings)if(o.swing!=null)o.swing=-o.swing;}for(const r of [...(c.rooms??[]),...(c.extensions??[])]){if(r.rect){const b=r.rect;r.rect=[m-b[2],b[1],m-b[0],b[3]];}if(r.polygon)r.polygon=r.polygon.map(point);if(r.labelPosition)r.labelPosition=point(r.labelPosition);if(r.local)r.local={origin:point(r.local.origin),u:vector(r.local.u),v:vector(r.local.v)};}for(const list of [c.floorPolygons,c.balconies])for(const r of list??[])r.polygon=r.polygon.map(point);if(c.spawn)c.spawn=point(c.spawn);for(const f of c.fixtures??[]){f.position=point(f.position);if(f.rotation!=null)f.rotation=-f.rotation;}if(c.entrance)c.entrance.inward=vector(c.entrance.inward);return c;}
export function openingPoints(w,o){const len=Math.hypot(w.b[0]-w.a[0],w.b[1]-w.a[1]),u=[(w.b[0]-w.a[0])/len,(w.b[1]-w.a[1])/len],a=[w.a[0]+u[0]*o.start,w.a[1]+u[1]*o.start],b=[a[0]+u[0]*o.width,a[1]+u[1]*o.width],h=o.hinge==='start'?a:b,end=o.hinge==='start'?b:a,v=[end[0]-h[0],end[1]-h[1]],t=(o.swing??0)*Math.PI/180;return {a,b,h,end,leaf:[h[0]+v[0]*Math.cos(t)-v[1]*Math.sin(t),h[1]+v[0]*Math.sin(t)+v[1]*Math.cos(t)]};}
export function validate(c){if(c?.schemaVersion!==2||c.units!=='mm'||c.orientation!=='line2-mirrored-x'||!Array.isArray(c.walls)||c.walls.length>200||!c.walls.length||!Array.isArray(c.rooms)||!c.review?.overlay||!Array.isArray(c.review.checks))throw Error('STEP 1 · 2호 라인 설정 파일이 아닙니다.');const ids=new Set(),finite=v=>Number.isFinite(v)&&Math.abs(v)<100000;for(const w of c.walls){if(!w.id||ids.has(w.id)||!Array.isArray(w.a)||!Array.isArray(w.b)||w.a.length!==2||w.b.length!==2||![...w.a,...w.b].every(finite)||!Array.isArray(w.openings)||!(w.thickness>0&&w.thickness<2000))throw Error('벽 좌표/ID/두께 오류');ids.add(w.id);const len=Math.hypot(w.a[0]-w.b[0],w.a[1]-w.b[1]);if(len<1)throw Error('벽 길이는 0보다 커야 합니다.');let last=0;for(const o of [...w.openings].sort((a,b)=>a.start-b.start)){if(!o.id||ids.has(o.id)||!['door','window'].includes(o.type)||!finite(o.start)||!finite(o.width)||o.start<last||o.width<=0||o.start+o.width>len+.001)throw Error('문/창이 벽을 벗어나거나 서로 겹칩니다.');if(o.type==='door'&&(!['start','end'].includes(o.hinge)||![90,-90].includes(o.swing)))throw Error('문 힌지/방향 오류');last=o.start+o.width;ids.add(o.id);}}for(const r of c.rooms)if(!Array.isArray(r.rect)||r.rect.length!==4||!r.rect.every(finite))throw Error('공간 좌표 오류');const t=c.review.overlay;if(![t.scale,t.offsetX,t.offsetY,t.rotation,t.opacity].every(finite)||t.scale<1||t.scale>200||t.opacity<0||t.opacity>1)throw Error('도면 정렬 값 오류');return c;}
const line=(a,b,color,width=45,extra='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${color}" stroke-width="${width}" ${extra}/>`;
export function geometry(c,{old=false,selected='',roomNames=true}={}){let out='';if(!old)for(const f of c.floorPolygons??[])out+=`<polygon points="${f.polygon.map(p=>p.join(',')).join(' ')}" fill="#e8eff2" fill-opacity=".2" stroke="#96a8b3" stroke-width="10"/>`;for(const w of c.walls){const color=old?'#7b8794':w.id===selected?'#a324cc':w.structureStatus==='STRUCTURE_UNCONFIRMED'?'#c17c16':'#007b83',len=Math.hypot(w.b[0]-w.a[0],w.b[1]-w.a[1]),u=[(w.b[0]-w.a[0])/len,(w.b[1]-w.a[1])/len],pt=s=>[w.a[0]+u[0]*s,w.a[1]+u[1]*s];out+=`<g data-id="${esc(w.id)}"><title>${esc(w.name??w.id)} / ${esc(w.evidence??'이전 추정')}</title>`;out+=line(w.a,w.b,'transparent',160,'class="hit"');let prev=0;for(const o of [...w.openings].sort((a,b)=>a.start-b.start)){out+=line(pt(prev),pt(o.start),color,old?45:55,old||w.kind==='unresolved'?'stroke-dasharray="110 75"':'');prev=o.start+o.width;}out+=line(pt(prev),w.b,color,old?45:55,old||w.kind==='unresolved'?'stroke-dasharray="110 75"':'');out+='</g>';for(const o of w.openings){const q=openingPoints(w,o),col=old?'#7b8794':o.id===selected?'#a324cc':o.removeGlazing?'#00a184':o.type==='window'?'#1c6feb':'#d56710';out+=`<g data-id="${esc(o.id)}"><title>${esc(o.id)} / ${esc(o.note)}</title>`;out+=line(q.a,q.b,'transparent',200,'class="hit"');out+=line(q.a,q.b,col,o.type==='window'?60:30,o.type==='door'||o.removeGlazing?'stroke-dasharray="65 45"':'');if(o.type==='door'&&o.hinge){out+=line(q.h,q.leaf,col,45);out+=`<path d="M ${q.end.join(' ')} A ${o.width} ${o.width} 0 0 ${o.swing>0?1:0} ${q.leaf.join(' ')}" fill="none" stroke="${col}" stroke-width="25"/><circle cx="${q.h[0]}" cy="${q.h[1]}" r="55" fill="${col}"/>`;}out+='</g>';}}
if(!old&&roomNames)for(const r of c.rooms){const b=r.rect,pos=r.labelPosition??[(b[0]+b[2])/2,(b[1]+b[3])/2];out+=`<text x="${pos[0]}" y="${pos[1]}" text-anchor="middle" font-size="260" font-family="sans-serif" fill="#1d303b" stroke="white" stroke-width="60" paint-order="stroke">${esc(r.name)}</text>`;}
return out;}
export function planSvg(c,{imageHref='floorplan.png',showImage=true,showOld=false,previous=null,selected='',roomNames=true,orientationLabel='2호 라인',viewBox='-1000 -900 9950 13200'}={}){const t=c.review.overlay;return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="${viewBox}" role="img" aria-label="2호 라인 평면 검증: 반전 원본 위에 벽 문 창 표시" style="width:100%;height:100%;background:#fff"><defs><pattern id="grid" width="1000" height="1000" patternUnits="userSpaceOnUse"><path d="M 1000 0 H 0 V 1000" fill="none" stroke="#e4eaf0" stroke-width="12"/></pattern></defs><rect x="-15000" y="-15000" width="40000" height="40000" fill="url(#grid)"/>${showImage?`<g opacity="${t.opacity}" transform="translate(${t.offsetX} ${t.offsetY}) rotate(${t.rotation}) scale(${t.scale}) translate(${c.review.sourceImage.width} 0) scale(-1 1)"><image xlink:href="${esc(imageHref)}" width="${c.review.sourceImage.width}" height="${c.review.sourceImage.height}"/></g>`:''}${showOld&&previous?`<g opacity=".65">${geometry(previous,{old:true,roomNames:false})}</g>`:''}${geometry(c,{selected,roomNames})}<g stroke="#526473" stroke-width="20">${line([0,-420],[7950,-420],'#526473',20)}${line([0,-540],[0,-280],'#526473',20)}${line([7950,-540],[7950,-280],'#526473',20)}</g><text x="3975" y="-550" text-anchor="middle" font-size="220" font-family="sans-serif" fill="#334856">7950 mm · 10750 − 2800</text><text x="3975" y="11800" text-anchor="middle" font-size="200" font-family="sans-serif" fill="#526473">${orientationLabel} · 동일 source geometry · 실측 전</text></svg>`;}

export function compileGeometry(c){const parts=[],openings=[];for(const w of c.walls){const length=Math.hypot(w.b[0]-w.a[0],w.b[1]-w.a[1]),u=[(w.b[0]-w.a[0])/length,(w.b[1]-w.a[1])/length],point=d=>[w.a[0]+u[0]*d,w.a[1]+u[1]*d];let count=0;const add=(start,end,y,height,kind='wall',thickness=w.thickness)=>{if(end<=start||height<=0)return;parts.push({id:w.id+':'+count++,wallId:w.id,a:point(start),b:point(end),thickness,y,height,kind,structureStatus:w.structureStatus});};let prev=0;for(const o of [...w.openings].sort((a,b)=>a.start-b.start)){add(prev,o.start,0,c.settings.ceilingHeight);const q=openingPoints(w,o);openings.push({...q,id:o.id,wallId:w.id,type:o.type,source:o});if(o.type==='window'){const sill=o.sill??c.settings.windowSill,height=o.height??c.settings.windowHeight;add(o.start,o.start+o.width,0,sill);if(!o.removeGlazing)add(o.start,o.start+o.width,sill,height,'glass');add(o.start,o.start+o.width,sill+height,c.settings.ceilingHeight-sill-height);}else{const h=o.height??c.settings.doorHeight;add(o.start,o.start+o.width,h,c.settings.ceilingHeight-h);parts.push({id:o.id+':leaf',wallId:w.id,a:q.h,b:o.open===false?q.end:q.leaf,thickness:c.settings.doorThickness,y:0,height:h,kind:'door'});}prev=o.start+o.width;}add(prev,length,0,c.settings.ceilingHeight);}
const colliders=parts.filter(p=>p.y<c.settings.eyeHeight&&p.y+p.height>0);return {source:c,parts,colliders,openings,floors:c.floorPolygons,rooms:c.rooms,balconies:c.balconies};}
export function entranceFrame(c){let wall,door;for(const w of c.walls){const o=w.openings.find(o=>o.id===c.entrance.openingId);if(o){wall=w;door=o;break;}}if(!door)throw Error('현관 개구부가 없습니다.');const q=openingPoints(wall,door),center=[(q.a[0]+q.b[0])/2,(q.a[1]+q.b[1])/2],n=c.entrance.inward,l=Math.hypot(...n),forward=[n[0]/l,n[1]/l],left=[forward[1],-forward[0]],outside=center.map((v,i)=>v-forward[i]*c.entrance.outsideDistance),living=c.rooms.find(r=>r.id==='living'),p=living.labelPosition;return {center,forward,left,outside,leftDistance:(p[0]-center[0])*left[0]+(p[1]-center[1])*left[1],livingLeft:(p[0]-center[0])*left[0]+(p[1]-center[1])*left[1]>0};}
export function localToWorld(room,[u,v]){return room.local.origin.map((x,i)=>x+room.local.u[i]*u+room.local.v[i]*v);}
export function containsPoint(poly,[x,z]){let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>z)!==(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])hit=!hit;}return hit;}
export function blocked(c,g,p){const r=c.settings.playerRadius,frame=entranceFrame(c);const rel=p.map((x,i)=>x-frame.center[i]),out=-rel.reduce((v,x,i)=>v+x*frame.forward[i],0),side=rel.reduce((v,x,i)=>v+x*frame.left[i],0);if(!g.floors.some(f=>containsPoint(f.polygon,p))&&!(out>=-200&&out<c.entrance.approachDepth&&Math.abs(side)<c.entrance.approachWidth/2))return true;return g.colliders.some(s=>{const dx=s.b[0]-s.a[0],dz=s.b[1]-s.a[1],len=Math.hypot(dx,dz),u=[dx/len,dz/len],v=[-u[1],u[0]],rel=[p[0]-(s.a[0]+s.b[0])/2,p[1]-(s.a[1]+s.b[1])/2],a=Math.max(Math.abs(rel[0]*u[0]+rel[1]*u[1])-len/2,0),b=Math.max(Math.abs(rel[0]*v[0]+rel[1]*v[1])-s.thickness/2,0);return a*a+b*b<r*r;});}
